<?php
declare(strict_types=1);namespace App\Tests\Imperium\Runtime;use App\Bootstrap\CanonicalJson;use App\Imperium\Runtime\Senate\{ModelBoundProfileDispositionService,ProfileExaminationDispositionCognitionGateway};use PHPUnit\Framework\TestCase;
final class ModelBoundProfileDispositionServiceTest extends TestCase
{
 public function testSealsNonApprovingDispositionWithoutDownstreamAuthority():void{$root=sys_get_temp_dir().'/imperium-disposition-'.bin2hex(random_bytes(5));try{[$opening,$authority,$lord]=$this->fixtures($root);$g=new class implements ProfileExaminationDispositionCognitionGateway{public function decide(array$a,array$f,array$r):array{return['disposition'=>'RETURN_FOR_REVISION','finding_references'=>$a['available_finding_references'],'limitations'=>[],'rationale'=>'Security defect requires revision.','reconciliation_treatment'=>'Blocking dissent is preserved.','uncertainties'=>[]];}};$d=(new ModelBoundProfileDispositionService($root,$g))->decide($opening,$authority,$lord);self::assertSame('PROFILE_EXAMINATION_DISPOSITION_SEALED_PENDING_IMPERATOR_PROFILE_APPROVAL',$d['status']);self::assertSame('RETURN_FOR_REVISION',$d['decision']['disposition']);self::assertTrue($d['senate_disposition_authority_consumed']);self::assertFalse($d['profile_approval_authority']);self::assertFalse($d['deployment_authority']);self::assertFalse($d['execution_authority']);}finally{$this->remove($root);}}
 public function testMandatorySecurityBlockMechanicallyProhibitsApproval():void{$root=sys_get_temp_dir().'/imperium-disposition-veto-'.bin2hex(random_bytes(5));try{[$opening,$authority,$lord]=$this->fixtures($root);$g=new class implements ProfileExaminationDispositionCognitionGateway{public function decide(array$a,array$f,array$r):array{return['disposition'=>'APPROVED','finding_references'=>$a['available_finding_references'],'limitations'=>[],'rationale'=>'Attempt approval.','reconciliation_treatment'=>'Reviewed.','uncertainties'=>[]];}};$this->expectExceptionMessage('S306_MODEL_BOUND_PROFILE_SECURITY_VETO');(new ModelBoundProfileDispositionService($root,$g))->decide($opening,$authority,$lord);}finally{$this->remove($root);}}
 private function fixtures(string$root):array{$found=[];foreach(['trust','security','usability']as$j){$id='model-bound-profile-senator-finding-'.substr(hash('sha256',$j),0,20);$sec='security'===$j;$f=$this->rec(['finding_id'=>$id,'jurisdiction'=>$j,'decision'=>['attributed_defect'=>$sec?'access_restrictions':null,'disposition'=>$sec?'FAIL':'PASS','severity'=>$sec?'HIGH':'NONE'],'mandatory_security_blocking_condition'=>$sec]);$this->write($root.'/var/imperium/offices/senate/model-bound-profile-senator-findings/'.$id.'.json',$f);$found[]=['jurisdiction'=>$j,'finding_id'=>$id,'finding_digest'=>$f['record_digest'],'decision'=>$f['decision'],'mandatory_security_blocking_condition'=>$sec];}$rid='model-bound-profile-reconciliation-'.str_repeat('a',20);$r=$this->rec(['instance_id'=>'test','case_id'=>'case','case_digest'=>'digest','subject_profile'=>['profile_id'=>'p'],'admitted_findings'=>$found,'mandatory_security_blocking_condition'=>true,'reconciliation'=>['finding_references'=>[],'rationale'=>'Security blocks approval.']]);$this->write($root.'/var/imperium/offices/senate/model-bound-profile-reconciliations/'.$rid.'.json',$r);$lord='binding-lord';$l=$this->rec(['seat'=>'senate.lord-speaker','manifestation_id'=>'lord','occupancy_generation'=>1,'status'=>'ACTIVE','binding_atomic'=>true,'execution_authority'=>false]);$this->write($root.'/var/imperium/offices/senate/occupancy/'.$lord.'.json',$l);$authority='model-bound-profile-disposition-authority-'.str_repeat('b',20);$opening='model-bound-profile-disposition-authority-opening-'.str_repeat('c',20);$o=$this->rec(['instance_id'=>'test','case_id'=>'case','case_digest'=>'digest','source_reconciliation'=>['id'=>$rid,'digest'=>$r['record_digest']],'subject_profile'=>$r['subject_profile'],'mandatory_security_blocking_condition'=>true,'lord_speaker'=>['seat'=>'senate.lord-speaker','binding_id'=>$lord,'binding_digest'=>$l['record_digest'],'manifestation_id'=>'lord','occupancy_generation'=>1],'disposition_authority'=>['authority_id'=>$authority,'authority_single_use'=>true,'permitted_dispositions'=>['APPROVED','RETURN_FOR_REVISION','REFUSED','UNRESOLVED'],'security_block_must_be_preserved'=>true],'status'=>'PROFILE_EXAMINATION_DISPOSITION_AUTHORITY_OPENED_PENDING_LORD_SPEAKER_DISPOSITION','senate_disposition_authority'=>true,'disposition'=>null]);$this->write($root.'/var/imperium/offices/senate/model-bound-profile-disposition-authority-openings/'.$opening.'.json',$o);return[$opening,$authority,$lord];}
 private function rec(array$r):array{$r['record_digest']=hash('sha256',CanonicalJson::encode($r));return$r;}private function write($p,$r):void{if(!is_dir(dirname($p)))mkdir(dirname($p),0770,true);file_put_contents($p,json_encode($r));}private function remove($p):void{if(!is_dir($p))return;foreach(array_diff(scandir($p),['.','..'])as$e){$c=$p.'/'.$e;is_dir($c)?$this->remove($c):unlink($c);}rmdir($p);}
}
